fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only indices 0 .. n/2 - 1 can have children
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        if left < n && a[i] > a[left] {
            return false;
        }
        let right = 2 * i + 2;
        if right < n && a[i] > a[right] {
            return false;
        }
    }
    true
}

